#include <iostream>
#include <memory>

int main() {
    auto p = std::make_unique<int>(42);   // dueño único
    std::cout << *p << '\n';              // 42

    auto q = std::move(p);                // transfiere la propiedad
    std::cout << (p == nullptr) << '\n';  // 1
    std::cout << *q << '\n';              // 42

    auto s = std::make_shared<int>(7);
    std::cout << s.use_count() << '\n';   // 1
    {
        auto copia = s;                   // comparte propiedad
        std::cout << s.use_count() << '\n'; // 2
    }
    std::cout << s.use_count() << '\n';   // 1

    std::weak_ptr<int> observador = s;    // no incrementa el contador
    std::cout << s.use_count() << '\n';   // 1
    if (auto fijado = observador.lock()) {
        std::cout << *fijado << '\n';     // 7
    }

    return 0;
}

#include <iostream>
#include <memory>

void mostrar(const std::unique_ptr<int>& p) {
    std::cout << *p << '\n';
}

int main() {
    std::unique_ptr<int> p = std::make_unique<int>(10);
    mostrar(p);              // 10

    std::unique_ptr<int> q = std::move(p);
    if (!p) {
        std::cout << "p ya no posee nada\n";
    }
    std::cout << *q << '\n'; // 10
    return 0;
}

#include <iostream>
#include <memory>
#include <string>
#include <vector>

struct Nodo {
    std::string nombre;
    std::vector<std::shared_ptr<Nodo>> hijos;
    std::weak_ptr<Nodo> padre;   // referencia sin propiedad
};

int main() {
    auto raiz = std::make_shared<Nodo>(Nodo{"raiz", {}, {}});
    auto hoja = std::make_shared<Nodo>(Nodo{"hoja", {}, raiz});

    raiz->hijos.push_back(hoja);

    std::cout << raiz->hijos.size() << '\n';     // 1
    std::cout << raiz.use_count() << '\n';       // 1
    std::cout << hoja.use_count() << '\n';       // 2
    std::cout << hoja->padre.expired() << '\n';  // 0

    if (auto p = hoja->padre.lock()) {
        std::cout << p->nombre << '\n';          // raiz
    }
    return 0;
}

#include <iostream>

class Buffer {
public:
    explicit Buffer(int n) : datos_(new int[n]{}), n_(n) {
        std::cout << "reserva " << n_ << '\n';
    }
    ~Buffer() {
        delete[] datos_;
        std::cout << "libera " << n_ << '\n';
    }

    Buffer(const Buffer&) = delete;
    Buffer& operator=(const Buffer&) = delete;

    int& operator[](int i) { return datos_[i]; }
    const int& operator[](int i) const { return datos_[i]; }
    int tam() const { return n_; }

private:
    int* datos_;
    int n_;
};

int main() {
    Buffer b(3);
    b[0] = 5;
    b[2] = 9;
    std::cout << b[0] + b[2] << '\n'; // 14
    return 0;
}

