struct Nodo {
    std::string nombre;
    std::shared_ptr<Nodo> otro;   // prueba a cambiarlo por weak_ptr
};

int main() {
    auto a = std::make_shared<Nodo>(Nodo{"a", nullptr});
    auto b = std::make_shared<Nodo>(Nodo{"b", nullptr});

    a->otro = b;
    b->otro = a;

    std::cout << a.use_count() << '\n'; // 2
